# typed: false
# frozen_string_literal: true

module GitHub::Goomba
  class TableOfContentsFilter < NodeFilter
    include ActionView::Helpers::OutputSafetyHelper

    SELECTOR = Goomba::Selector.new("h1, h2, h3, h4, h5, h6")

    # Public: Retrieves all anchor names generated by this filter from the
    # scratch hash.
    #
    # Returns a Hash of String to true.
    def self.generated_anchors(scratch)
      scratch[:toc_anchors] || {}
    end

    def self.cache_key(context)
      nil unless
      [
        ("toc_anchor_prefix=#{context[:name_prefix]}" if context[:name_prefix]),
        ("toc_anchor_icon=#{context[:anchor_icon]}" if context[:anchor_icon])
      ].reject(&:blank?).join(":")
    end

    def initialize(*args)
      super
      scratch[:toc_anchors] = {}
      @anchor_icon = context[:anchor_icon].nil? ? anchor_icon : context[:anchor_icon]
      @anchors = Hash.new { |h, k| h[k] = [] }
      result[:toc_headers_hash] = []
    end

    def selector
      SELECTOR
    end

    def scan(document)
      # track the last "uniqueness" value for each heading id
      last_id_uniq_value = Hash.new(0)

      # track seen anchors to handle cases where a non-unique header id might clash
      # with a generated unique header id, e.g.
      # HEADER -> id is `header`
      # HEADER -> id is `header-1` to not clash with the first HEADER
      # HEADER 1 -> id would be `header-1` and would cause a name collision
      seen_anchors = Set.new

      document.select(SELECTOR).each do |element|
        next if element.children.empty?

        id = heading_id(element)

        anchor = ""
        uniq = last_id_uniq_value[id]
        loop do
          suffix = uniq > 0 ? "-#{uniq}" : ""
          anchor = "#{id}#{suffix}"
          uniq += 1
          break if !seen_anchors.include?(anchor)
        end

        last_id_uniq_value[id] = uniq

        @anchors[id] << anchor
        seen_anchors << anchor
        scratch[:toc_anchors][prefix_anchor(anchor)] = true

        # Used for inline TOC view
        result[:toc_headers_hash].push(
          level: element_level(element),
          text: parse_text(element),
          anchor: anchor
        )
      end
    end

    def call(element)
      id = heading_id(element)
      anchor = @anchors[id].shift
      return unless anchor

      if context[:add_tabindex_to_headings]
        element["tabindex"] = "-1"
      end
      element["class"] = "heading-element"

      attrs = {
        id: prefix_anchor(anchor),
        class: :anchor,
        "aria-label": "Permalink: #{parse_text(element)}",
      }

      inner_html = safe_join([
        ActionController::Base.helpers.content_tag(
          element.tag.to_sym,
          safe_html_if_sanitized(element.inner_html),
          **element.attributes,
        ),
        ActionController::Base.helpers.link_to(@anchor_icon, "##{anchor}", attrs)
      ])

      # We return a DocumentFragment here because we want to continue running filters on the children. Once
      # Goomba's updated to recurse filters on individual returned elements, we can remove this fragment wrapper
      Goomba::DocumentFragment.new(ActionController::Base.helpers.content_tag(:div, inner_html, class: "markdown-heading"))
    end

    private

    def element_level(element)
      /\d/.match(element.tag).to_s.to_i
    end

    def parse_text(element)
      # Remove any footnote references from the heading
      element.select(match: ":text", reject: "sup :text")
        .map(&:text_content)
        .join
    end

    def anchor_icon
      GitHub::HTML::TableOfContentsFilter.new("").anchor_icon
    end

    def heading_id(element)
      text = element.text_content
      id = text.downcase
      id.gsub!(GitHub::HTML::TableOfContentsFilter::PUNCTUATION_REGEXP, "") # remove punctuation
      id.gsub!(" ", "-") # replace spaces with dash
      id
    end

    def prefix_anchor(anchor)
      prefix = context[:name_prefix] || ""
      # FIXME: It would probably be better not to add an anchor at all for
      # text-less headings (or perhaps to generate a unique non-empty anchor
      # name), but for now we'll match HTML::Pipeline's behavior.
      anchor.empty? ? anchor : "#{prefix}#{anchor}"
    end
  end
end
